pub fn format_sarif(
    surfaces: &[cargo_lock::NativeSurface],
    malicious: &[&cargo_lock::Package],
    lockfile_uri: &str,
) -> Result<String> {
    let mut results = Vec::new();

    for surface in surfaces {
        let rule_id = if surface.has_proc_macro {
            "SANDBOX001-PROC-MACRO"
        } else {
            "SANDBOX002-BUILD-SCRIPT"
        };
        let text = format!(
            "Native surface detected in {}@{}: {}",
            surface.package.name,
            surface.package.version,
            if surface.has_proc_macro {
                "proc-macro"
            } else {
                "build script"
            }
        );
        results.push(SarifResult {
            rule_id,
            level: "warning",
            message: SarifMessage { text },
            locations: vec![SarifLocation {
                physical_location: SarifPhysicalLocation {
                    artifact_location: SarifArtifactLocation { uri: lockfile_uri },
                },
            }],
        });
    }

    for m in malicious {
        let text = format!("Known malicious package detected: {}@{}", m.name, m.version);
        results.push(SarifResult {
            rule_id: "SANDBOX000-MALICIOUS",
            level: "error",
            message: SarifMessage { text },
            locations: vec![SarifLocation {
                physical_location: SarifPhysicalLocation {
                    artifact_location: SarifArtifactLocation { uri: lockfile_uri },
                },
            }],
        });
    }

    let log = SarifLog {
        schema: "https://raw.githubusercontent.com/oasis-tcs/sarif-spec/master/Schemata/sarif-schema-2.1.0.json",
        version: "2.1.0",
        runs: vec![SarifRun {
            tool: SarifTool {
                driver: SarifDriver {
                    name: "sandbox-ffi-layers",
                    version: env!("CARGO_PKG_VERSION"),
                },
            },
            results,
        }],
    };

    Ok(serde_json::to_string_pretty(&log)?)
}

pub fn write_output(content: &str, output_path: Option<&Path>) -> Result<()> {
    if let Some(path) = output_path {
        std::fs::write(path, content)?;
    } else {
        print!("{}", content);
    }
    Ok(())
}

fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("sandbox_ffi_layers=info")
        .init();

    let args = Cli::parse();

    if args.check {
        let format: Format = args.format.parse()?;
        let lockfile_path = validate_lockfile_path(&args.lockfile)?;
        let content = read_lockfile(&lockfile_path)?;
        let packages = cargo_lock::parse_cargo_lock(&content)?;
        let surfaces = cargo_lock::analyze_native_surface(&packages);

        tracing::info!(
            "Analyzed {} packages, {} have native build surface",
            packages.len(),
            surfaces.len()
        );

        let malicious: Vec<_> = packages
            .iter()
            .filter(|p| p.name == "proc-macro1" || p.name == "proc-macro-en")
            .collect();

        let output_content = match format {
            Format::Text => format_text(&surfaces, &malicious),
            Format::Json => format_json(&surfaces, &malicious)?,
            Format::Sarif => format_sarif(&surfaces, &malicious, &args.lockfile)?,
        };

        write_output(&output_content, args.output.as_deref())?;

        if !malicious.is_empty() && args.fail_critical {
            std::process::exit(1);
        }
    } else if args.watch {
        eprintln!("Watch mode requires eBPF support (coming in v0.2.0)");
        eprintln!("Use --check for one-shot analysis");
        std::process::exit(2);
    } else {
        println!("sandbox-ffi-layers v{}", env!("CARGO_PKG_VERSION"));
        println!("Use --check to analyze a Cargo.lock, or --watch for runtime monitoring");
    }

    Ok(())
}

